.darma-loader-tw-modal-skeleton { display: flex; flex-direction: column; gap: calc(var(--loader-size, 200px) * .04); width: var(--loader-size, 200px); padding: calc(var(--loader-size, 200px) * .06); border-radius: calc(var(--loader-size, 200px) * .07); background: color-mix(in srgb, var(--loader-color, #64748b) 12%, transparent); box-shadow: 0 calc(var(--loader-size, 200px) * .02) calc(var(--loader-size, 200px) * .05) rgba(15, 23, 42, .12); box-sizing: border-box; animation: darma-loader-tw-modal-skeleton-twPulse calc(var(--loader-speed, 1s) * 1.8) cubic-bezier(.4, 0, .6, 1) infinite; }
.darma-loader-tw-modal-skeleton .darma-loader-tw-modal-skeleton__head { width: 55%; height: calc(var(--loader-size, 200px) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #64748b) 48%, transparent); }
.darma-loader-tw-modal-skeleton .darma-loader-tw-modal-skeleton__body { height: calc(var(--loader-size, 200px) * .045); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #64748b) 26%, transparent); }
.darma-loader-tw-modal-skeleton .darma-loader-tw-modal-skeleton__actions { display: flex; justify-content: flex-end; gap: calc(var(--loader-size, 200px) * .04); margin-top: calc(var(--loader-size, 200px) * .03); }
.darma-loader-tw-modal-skeleton .darma-loader-tw-modal-skeleton__actions i { width: 22%; height: calc(var(--loader-size, 200px) * .075); border-radius: calc(var(--loader-size, 200px) * .025); background: color-mix(in srgb, var(--loader-color, #64748b) 38%, transparent); }
@keyframes darma-loader-tw-modal-skeleton-twPulse { 50% { opacity: .5; } }

